function validate([target, words, costs]) {
  if (target.length < 1 || target.length > 50000) return 'target needs 1 to 5 * 10^4 letters.';
  if (!/^[a-z]+$/.test(target)) return 'target uses only lowercase English letters.';
  if (words.length < 1 || words.length > 50000) return 'words needs 1 to 5 * 10^4 entries.';
  if (costs.length !== words.length) return 'costs needs exactly one cost per word.';
  let total = 0;
  for (const word of words) {
    if (!/^[a-z]+$/.test(word)) return 'Each word is nonempty and uses only lowercase English letters.';
    if (word.length > target.length) return 'No word may be longer than target.';
    total += word.length;
  }
  if (total > 50000) return 'The words may have at most 5 * 10^4 letters in total.';
  if (costs.some(c => !Number.isInteger(c) || c < 1 || c > 10000)) return 'Each cost is an integer from 1 to 10^4.';
  return null;
}

