function minimumCost(target, words, costs) {
  const children = [new Map()];
  const cheapest = [Infinity];
  const depth = [0];
  for (let w = 0; w < words.length; w++) {
    let node = 0;
    for (const letter of words[w]) {
      if (!children[node].has(letter)) {
        children[node].set(letter, children.length);
        children.push(new Map());
        cheapest.push(Infinity);
        depth.push(depth[node] + 1);
      }
      node = children[node].get(letter);
    }
    cheapest[node] = Math.min(cheapest[node], costs[w]);
  }
  const fail = new Array(children.length).fill(0);
  const wordLink = new Array(children.length).fill(0);
  const queue = [...children[0].values()];
  for (let head = 0; head < queue.length; head++) {
    const parent = queue[head];
    for (const [letter, child] of children[parent]) {
      let link = fail[parent];
      while (link !== 0 && !children[link].has(letter)) {
        link = fail[link];
      }
      fail[child] = children[link].get(letter) ?? 0;
      wordLink[child] = cheapest[fail[child]] < Infinity ? fail[child] : wordLink[fail[child]];
      queue.push(child);
    }
  }
  const dp = new Array(target.length + 1).fill(Infinity);
  dp[0] = 0;
  let state = 0;
  for (let i = 1; i <= target.length; i++) {
    const letter = target[i - 1];
    while (state !== 0 && !children[state].has(letter)) {
      state = fail[state];
    }
    state = children[state].get(letter) ?? 0;
    let match = cheapest[state] < Infinity ? state : wordLink[state];
    while (match !== 0) {
      dp[i] = Math.min(dp[i], dp[i - depth[match]] + cheapest[match]);
      match = wordLink[match];
    }
  }
  return dp[target.length] === Infinity ? -1 : dp[target.length];
}

