function minimumCost(target, words, costs) {
  // best[i] is the cheapest way to build target's suffix from i, trying every word at every position.
  const n = target.length;
  const best = new Array(n + 1).fill(Infinity);
  best[n] = 0;
  for (let i = n - 1; i >= 0; i--) {
    for (let w = 0; w < words.length; w++) {
      if (target.startsWith(words[w], i)) best[i] = Math.min(best[i], costs[w] + best[i + words[w].length]);
    }
  }
  return best[0] === Infinity ? -1 : best[0];
}

