function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abc'.slice(0, pick(1, 3));
  const randomWord = length => Array.from({ length }, () => letters[pick(0, letters.length - 1)]).join('');
  const large = size === 'large';
  const target = randomWord(large ? pick(8000, 10000) : pick(1, 8));
  const count = large ? pick(800, 1500) : pick(1, 5);
  const longest = Math.min(target.length, large ? (letters.length === 1 ? 80 : 12) : 4);
  const words = [], costs = [];
  let total = 0;
  while (words.length < count) {
    const length = pick(1, longest);
    if (total + length > 50000) break;
    const start = pick(0, target.length - length);
    words.push(rand() < (large ? 0.9 : 0.7) ? target.slice(start, start + length) : randomWord(length));
    costs.push(large ? pick(1, 10000) : pick(1, 20));
    total += length;
  }
  return [target, words, costs];
}
